/* In masscan, the rate is stored in a scan_config struct.
 * Let's try different approaches */

/* Approach 1: store as cycles per packet (RATE_CYCLES = 100000000 = 100MHz?) */
void rate_fmt_approach1(double rate) {
    /* tokenbucket stores as: tokens_per_second = rate
