    uint64_t cycles = (uint64_t)(100000000.0 / rate);
    double rate_back = 100000000.0 / cycles;

    printf("A1 rate=%g -> cycles=%llu -> rate_back=%g", rate, cycles, rate_back);
    if (rate_back == (double)(uint64_t)rate_back)
        printf(" INTEGER\n");
    else
