void rate_fmt_approach2(double rate) {
    /* Check if floor(rate) == rate */
    printf("A2 rate=%g floor=%g", rate, floor(rate));
    if (floor(rate) == rate)
        printf(" INTEGER\n");
    else
        printf(" FLOAT\n");
}

/* Approach 3: tokenbucket using 1/1000000 second intervals */
