    uint64_t cycles = (uint64_t)(1000000.0 / rate);
    double rate_back = 1000000.0 / cycles;

    printf("A3 rate=%g -> cycles=%llu -> rate_back=%g", rate, cycles, rate_back);
    if (rate_back == (double)(uint64_t)rate_back)
        printf(" INTEGER\n");
    else
        printf(" FLOAT\n");
}

