/*
 * masscan - a port scanner implementation
 * Based on masscan 1.3.9
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdarg.h>
#include <math.h>
#include <errno.h>
#include <time.h>
#include <ctype.h>
#include <limits.h>
