   Configuration
   =========================== */
#define MAX_RANGES 65536
#define MAX_PORTS  65536
#define MAX_NOCAPTURE 16

struct NocaptureList {
    char *items[MAX_NOCAPTURE];
    int count;
};

struct OutputConfig {
    char *filename;
    char *format;  /* xml, json, ndjson, grepable, binary, unicornscan, list */
    int append;
};

