    char *adapter;
    char adapter_ip[64];
    uint8_t adapter_mac[6];
    int adapter_mac_set;
    uint8_t router_mac_ipv4[6];
    int router_mac_ipv4_set;
    uint8_t router_mac_ipv6[6];
    int router_mac_ipv6_set;
    int adapter_port;
    int adapter_port_set;
};

struct MasscanConfig {
    uint64_t seed;
    int seed_set;
    double rate;

    /* Shard */
    unsigned shard_num;
    unsigned shard_total;

    /* Banners */
    int banners;

    /* Nocapture */
    struct NocaptureList nocapture;

    /* Output */
    struct OutputConfig output;

    /* Adapter */
    struct AdapterConfig adapter;

    /* Resume */
    uint64_t resume_index;
    int resume_index_set;
    uint64_t resume_count;
    int resume_count_set;

    /* Verbosity */
    int verbosity;
    int debug_level;

    /* Scanning options */
    int open_only;
    int packet_trace;
    int ping;
    int ttl;
    int ttl_set;
    int connection_timeout;

    /* Internal */
    int do_echo;
    int do_help;
    int do_nmap;
    int do_version;
    int do_list_interfaces;
    int do_readscan;
    char *readscan_file;

    /* Ports */
    struct portrange ports[MAX_PORTS * 2];
    int nports;

    /* Ranges */
    struct iprange ranges[MAX_RANGES];
    int nranges;

    /* Exclude ranges */
    struct iprange excludes[MAX_RANGES];
    int nexcludes;
};

/* ===========================
   Global pcap function pointers
   =========================== */
static int g_pcap_loaded = 0;
static void *g_pcap_handle = NULL;

typedef void (*pcap_close_fn)(void *);
typedef int (*pcap_datalink_fn)(void *);
typedef int (*pcap_dispatch_fn)(void *, int, void *, void *);
typedef int (*pcap_findalldevs_fn)(void **, char *);
typedef void (*pcap_freealldevs_fn)(void *);
typedef const char *(*pcap_lib_version_fn)(void);
typedef char *(*pcap_lookupdev_fn)(char *);
typedef int (*pcap_major_version_fn)(void *);
typedef int (*pcap_minor_version_fn)(void *);
typedef void *(*pcap_open_live_fn)(const char *, int, int, int, char *);
typedef void *(*pcap_open_offline_fn)(const char *, char *);
typedef int (*pcap_sendpacket_fn)(void *, const unsigned char *, int);
typedef const unsigned char *(*pcap_next_fn)(void *, void *);
typedef int (*pcap_setdirection_fn)(void *, int);
typedef const char *(*pcap_datalink_val_to_name_fn)(int);
typedef void (*pcap_perror_fn)(void *, const char *);
typedef char *(*pcap_geterr_fn)(void *);
typedef void *(*pcap_create_fn)(const char *, char *);
typedef int (*pcap_set_snaplen_fn)(void *, int);
typedef int (*pcap_set_promisc_fn)(void *, int);
typedef int (*pcap_set_timeout_fn)(void *, int);
typedef int (*pcap_set_immediate_mode_fn)(void *, int);
typedef int (*pcap_set_buffer_size_fn)(void *, int);
typedef int (*pcap_set_rfmon_fn)(void *, int);
typedef int (*pcap_can_set_rfmon_fn)(void *);
typedef int (*pcap_activate_fn)(void *);

struct PcapFuncs {
    pcap_close_fn pcap_close;
    pcap_datalink_fn pcap_datalink;
    pcap_dispatch_fn pcap_dispatch;
    pcap_findalldevs_fn pcap_findalldevs;
    pcap_freealldevs_fn pcap_freealldevs;
    pcap_lib_version_fn pcap_lib_version;
    pcap_lookupdev_fn pcap_lookupdev;
    pcap_major_version_fn pcap_major_version;
    pcap_minor_version_fn pcap_minor_version;
    pcap_open_live_fn pcap_open_live;
    pcap_open_offline_fn pcap_open_offline;
    pcap_sendpacket_fn pcap_sendpacket;
    pcap_next_fn pcap_next;
    pcap_setdirection_fn pcap_setdirection;
    pcap_datalink_val_to_name_fn pcap_datalink_val_to_name;
    pcap_perror_fn pcap_perror;
    pcap_geterr_fn pcap_geterr;
    pcap_create_fn pcap_create;
    pcap_set_snaplen_fn pcap_set_snaplen;
    pcap_set_promisc_fn pcap_set_promisc;
    pcap_set_timeout_fn pcap_set_timeout;
    pcap_set_immediate_mode_fn pcap_set_immediate_mode;
    pcap_set_buffer_size_fn pcap_set_buffer_size;
    pcap_set_rfmon_fn pcap_set_rfmon;
    pcap_can_set_rfmon_fn pcap_can_set_rfmon;
    pcap_activate_fn pcap_activate;
};

static struct PcapFuncs pcap = {0};

/* List of pcap libraries to try */
static const char *pcap_libs[] = {
    "libpcap.so",
    "libpcap.A.dylib",
    "libpcap.dylib",
    "libpcap.so.1",
    "libpcap.so.0.9.5",
    "libpcap.so.0.9.4",
    "libpcap.so.0.8",
    NULL
};

static int pcap_load_function(void *handle, const char *name, void **fn_ptr, int verbose) {
    *fn_ptr = dlsym(handle, name);
    if (*fn_ptr == NULL) {
        if (verbose)
            fprintf(stderr, "pcap: %s: failed\n", name);
        return 0;
    }
    return 1;
}

static void pcap_init(int verbose) {
    const char **lib;

    for (lib = pcap_libs; *lib != NULL; lib++) {
        if (verbose) {
            fprintf(stderr, "[-] pcap: failed to load: %s\n", *lib);
        }
        g_pcap_handle = dlopen(*lib, RTLD_LAZY);
        if (g_pcap_handle) {
            /* Successfully loaded */
            /* Don't print the failure for this one */
            break;
        }
    }

    if (g_pcap_handle == NULL) {
        fprintf(stderr, "[-] FAIL: failed to load libpcap shared library\n");
        fprintf(stderr, "    [hint]: you must install libpcap or WinPcap\n");

        if (verbose) {
            /* Print stub/failed status for each function */
            const char *funcs[] = {
                "pcap_close", "pcap_datalink", "pcap_dispatch",
                "pcap_findalldevs", "pcap_freealldevs", "pcap_lib_version",
                "pcap_lookupdev", "pcap_major_version", "pcap_minor_version",
                "pcap_open_live", "pcap_open_offline", "pcap_sendpacket",
                "pcap_next", "pcap_setdirection", "pcap_datalink_val_to_name",
                "pcap_perror", "pcap_geterr", "pcap_create", "pcap_set_snaplen",
                "pcap_set_promisc", "pcap_set_timeout", "pcap_set_immediate_mode",
                "pcap_set_buffer_size", "pcap_set_rfmon", "pcap_can_set_rfmon",
                "pcap_activate", NULL
            };
            for (int i = 0; funcs[i]; i++) {
                fprintf(stderr, "pcap: %s: failed\n", funcs[i]);
            }
        }
        return;
    }

    /* Load all functions */
    #define LOAD_FN(name) pcap_load_function(g_pcap_handle, #name, (void**)&pcap.name, 0)
    LOAD_FN(pcap_close);
    LOAD_FN(pcap_datalink);
    LOAD_FN(pcap_dispatch);
    LOAD_FN(pcap_findalldevs);
    LOAD_FN(pcap_freealldevs);
    LOAD_FN(pcap_lib_version);
    LOAD_FN(pcap_lookupdev);
    LOAD_FN(pcap_major_version);
    LOAD_FN(pcap_minor_version);
    LOAD_FN(pcap_open_live);
    LOAD_FN(pcap_open_offline);
    LOAD_FN(pcap_sendpacket);
    LOAD_FN(pcap_next);
    LOAD_FN(pcap_setdirection);
    LOAD_FN(pcap_datalink_val_to_name);
    LOAD_FN(pcap_perror);
    LOAD_FN(pcap_geterr);
    LOAD_FN(pcap_create);
    LOAD_FN(pcap_set_snaplen);
    LOAD_FN(pcap_set_promisc);
    LOAD_FN(pcap_set_timeout);
    LOAD_FN(pcap_set_immediate_mode);
    LOAD_FN(pcap_set_buffer_size);
    LOAD_FN(pcap_set_rfmon);
    LOAD_FN(pcap_can_set_rfmon);
    LOAD_FN(pcap_activate);
    #undef LOAD_FN

    g_pcap_loaded = 1;
}
EOF

