/* Random 64-bit seed using /dev/urandom or time */
static uint64_t random_seed(void) {
    uint64_t val = 0;
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd >= 0) {
        if (read(fd, &val, 8) != 8) val = 0;
        close(fd);
    }
    if (!val) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        val = (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;
        val ^= (uint64_t)getpid() << 32;
    }
    return val;
}

/* Format rate for --echo output */
static void fmt_rate(double rate, char *buf, size_t bufsz) {
    double intpart;
    int is_int = (modf(rate, &intpart) == 0.0);
    if (!is_int || (uint64_t)(rate * 100000.0) > 0xFFFFFFFFULL)
        snprintf(buf, bufsz, "%.6f", rate);
    else
        snprintf(buf, bufsz, "%-10g", rate);
}

/* Parse a MAC address string "XX:XX:XX:XX:XX:XX" or "XX-XX-XX-XX-XX-XX" */
static int parse_mac(const char *str, uint8_t mac[6]) {
    unsigned a,b,c,d,e,f;
    if (sscanf(str, "%x:%x:%x:%x:%x:%x", &a,&b,&c,&d,&e,&f)==6 ||
        sscanf(str, "%x-%x-%x-%x-%x-%x", &a,&b,&c,&d,&e,&f)==6) {
        mac[0]=a; mac[1]=b; mac[2]=c;
        mac[3]=d; mac[4]=e; mac[5]=f;
        return 1;
    }
    return 0;
}

/* Format MAC as XX-XX-XX-XX-XX-XX */
static void fmt_mac(const uint8_t mac[6], char *buf, size_t bufsz) {
    snprintf(buf, bufsz, "%02x-%02x-%02x-%02x-%02x-%02x",
             mac[0],mac[1],mac[2],mac[3],mac[4],mac[5]);
}

/* Convert string to lowercase */
static void str_lower(char *s) {
    while (*s) { *s = tolower((unsigned char)*s); s++; }
}

/* Strip leading/trailing whitespace */
static char *str_trim(char *s) {
    char *e;
    while (isspace((unsigned char)*s)) s++;
    e = s + strlen(s);
    while (e > s && isspace((unsigned char)*(e-1))) e--;
    *e = '\0';
    return s;
}

