/* ============================================================ */

static uint32_t parse_ipv4(const char *str) {
    struct in_addr addr;
    if (inet_pton(AF_INET, str, &addr) == 1)
        return ntohl(addr.s_addr);
    return 0xFFFFFFFF; /* invalid */
}

static void fmt_ipv4(uint32_t ip, char *buf, size_t sz) {
    snprintf(buf, sz, "%u.%u.%u.%u",
             (ip>>24)&0xFF,(ip>>16)&0xFF,(ip>>8)&0xFF,ip&0xFF);
}

/* Check if a range [first..last] can be expressed as a CIDR block */
static int range_to_cidr(uint32_t first, uint32_t last, int *prefix_len) {
    if (first > last) return 0;
    uint32_t diff = last - first + 1;
    /* diff must be a power of 2 */
    if ((diff & (diff-1)) != 0) return 0;
    /* first must be aligned */
    if (first & (diff-1)) return 0;
    /* compute prefix length */
    int bits = 0;
    uint32_t tmp = diff;
    while (tmp > 1) { tmp >>= 1; bits++; }
    *prefix_len = 32 - bits;
    return 1;
}

/* Format an IPv4 range for echo output */
static void fmt_ipv4_range(uint32_t first, uint32_t last, char *buf, size_t sz) {
    int plen;
    char f[32], l[32];
    if (first == last) {
        fmt_ipv4(first, buf, sz);
        return;
    }
    if (range_to_cidr(first, last, &plen)) {
        fmt_ipv4(first, f, sizeof(f));
        snprintf(buf, sz, "%s/%d", f, plen);
        return;
    }
    fmt_ipv4(first, f, sizeof(f));
    fmt_ipv4(last, l, sizeof(l));
    snprintf(buf, sz, "%s-%s", f, l);
}

/* Parse "a.b.c.d", "a.b.c.d/N", "a.b.c.d-e.f.g.h" */
/* Returns 1 on success, 0 on failure */
/* Sets *is_v6 = 0 for IPv4 */
static int parse_ip_range(const char *str, iprange_t *out) {
    char tmp[256];
    strncpy(tmp, str, sizeof(tmp)-1);
    tmp[sizeof(tmp)-1] = '\0';

    /* Check for IPv6 */
    if (strchr(tmp, ':')) {
        /* IPv6 */
        out->is_v6 = 1;
        char *slash = strchr(tmp, '/');
        if (slash) {
            *slash = '\0';
            int prefix = atoi(slash+1);

            struct in6_addr addr6;
            if (inet_pton(AF_INET6, tmp, &addr6) != 1) return 0;

            /* first = addr6 masked to prefix */
            /* last = addr6 with suffix bits set */
            uint8_t *ab = addr6.s6_addr;

            /* Store as hi/lo uint64 (network order -> host order) */
            uint64_t hi = 0, lo = 0;
            for (int i = 0; i < 8; i++) hi = (hi << 8) | ab[i];
            for (int i = 8; i < 16; i++) lo = (lo << 8) | ab[i];

            /* Mask to prefix */
            uint64_t fhi = hi, flo = lo;
            uint64_t lhi = hi, llo = lo;

            if (prefix <= 64) {
                uint64_t mask = (prefix == 0) ? 0 : (~0ULL << (64-prefix));
                fhi &= mask; flo = 0;
                lhi |= ~mask; llo = 0xFFFFFFFFFFFFFFFFULL;
            } else {
                uint64_t mask = ~0ULL << (128-prefix);
                flo &= mask;
                llo |= ~mask;
            }

            out->first.v6.hi = fhi; out->first.v6.lo = flo;
            out->last.v6.hi = lhi; out->last.v6.lo = llo;
        } else {
            struct in6_addr addr6;
            if (inet_pton(AF_INET6, tmp, &addr6) != 1) return 0;
            uint8_t *ab = addr6.s6_addr;
            uint64_t hi = 0, lo = 0;
            for (int i = 0; i < 8; i++) hi = (hi << 8) | ab[i];
            for (int i = 8; i < 16; i++) lo = (lo << 8) | ab[i];
            out->first.v6.hi = out->last.v6.hi = hi;
            out->first.v6.lo = out->last.v6.lo = lo;
        }
        return 1;
    }

    /* IPv4 */
    out->is_v6 = 0;

    /* Check for CIDR */
    char *slash = strchr(tmp, '/');
    if (slash) {
        *slash = '\0';
        int prefix = atoi(slash+1);
        struct in_addr addr4;
        if (inet_pton(AF_INET, tmp, &addr4) != 1) return 0;
        uint32_t ip = ntohl(addr4.s_addr);
        /* Mask to network */
        uint32_t mask = (prefix == 0) ? 0 : (~0U << (32-prefix));
        out->first.v4 = ip & mask;
        out->last.v4 = ip | ~mask;
        return 1;
    }

    /* Check for range a.b.c.d-e.f.g.h */
    char *dash = NULL;
    /* Find a dash that's not in the IP address dotted notation */
    /* The IP has dots, so we look for a dash after the last digit group */
    char *p = tmp;
    int dotcount = 0;
    while (*p) {
        if (*p == '.') dotcount++;
        if (*p == '-' && dotcount >= 3) { dash = p; break; }
        p++;
    }

    if (dash) {
        *dash = '\0';
        struct in_addr a1, a2;
        if (inet_pton(AF_INET, tmp, &a1) != 1) return 0;
        if (inet_pton(AF_INET, dash+1, &a2) != 1) return 0;
        out->first.v4 = ntohl(a1.s_addr);
        out->last.v4 = ntohl(a2.s_addr);
        return 1;
    }

    /* Single IP */
    struct in_addr addr4;
    if (inet_pton(AF_INET, tmp, &addr4) != 1) return 0;
    out->first.v4 = out->last.v4 = ntohl(addr4.s_addr);
    return 1;
}

