        if (lo <= hi) {
            if (ntmp < MAX_RANGES) {
                tmp[ntmp].is_v6 = 0;
                tmp[ntmp].first.v4 = lo;
                tmp[ntmp].last.v4 = hi;
                ntmp++;
            }
        }
        done_range:;
    }

    memcpy(inc, tmp, ntmp * sizeof(iprange_t));
    *ninc = ntmp;
}

/* Print IPv6 range */
static void fmt_ipv6_range(const iprange_t *r, char *buf, size_t sz) {
    /* Calculate prefix length */
    uint64_t fhi = r->first.v6.hi, flo = r->first.v6.lo;
    uint64_t lhi = r->last.v6.hi, llo = r->last.v6.lo;

    /* Try to express as CIDR */
    uint64_t dhi = ~(fhi ^ lhi);
    uint64_t dlo = ~(flo ^ llo);

    /* Count common bits from high end */
    int prefix = 0;
    /* Check high 64 bits */
    for (int bit = 63; bit >= 0; bit--) {
        if ((dhi >> bit) & 1) prefix++;
        else break;
    }
    /* If all 64 high bits match, check low 64 */
    if (prefix == 64) {
        for (int bit = 63; bit >= 0; bit--) {
            if ((dlo >> bit) & 1) prefix++;
            else break;
        }
    }

    /* Verify it's a proper CIDR */
    int is_cidr = 1;
    if (prefix < 64) {
        /* low bits of hi should be all 0 in first and all 1 in last */
        uint64_t mask = (prefix == 0) ? 0 : (~0ULL << (64 - prefix));
        if ((fhi & ~mask) != 0 || (lhi & ~mask) != ~mask) is_cidr = 0;
        if (flo != 0 || llo != 0xFFFFFFFFFFFFFFFFULL) is_cidr = 0;
    } else {
        uint64_t mask = (prefix == 128) ? ~0ULL : (~0ULL << (128 - prefix));
        if ((flo & ~mask) != 0 || (llo & ~mask) != ~mask) is_cidr = 0;
    }

    /* Convert first to string */
    struct in6_addr addr6;
    uint8_t *ab = addr6.s6_addr;
    for (int i = 0; i < 8; i++) ab[i] = (fhi >> (56 - i*8)) & 0xFF;
    for (int i = 0; i < 8; i++) ab[8+i] = (flo >> (56 - i*8)) & 0xFF;

    char ipstr[INET6_ADDRSTRLEN];
    inet_ntop(AF_INET6, &addr6, ipstr, sizeof(ipstr));

    if (is_cidr) {
        snprintf(buf, sz, "%s/%d", ipstr, prefix);
    } else {
        struct in6_addr last6;
        uint8_t *lb = last6.s6_addr;
        for (int i = 0; i < 8; i++) lb[i] = (lhi >> (56 - i*8)) & 0xFF;
        for (int i = 0; i < 8; i++) lb[8+i] = (llo >> (56 - i*8)) & 0xFF;
        char laststr[INET6_ADDRSTRLEN];
        inet_ntop(AF_INET6, &last6, laststr, sizeof(laststr));
        snprintf(buf, sz, "%s-%s", ipstr, laststr);
    }
}

