/* Parse port spec: "80", "80-90", "U:53", "T:443", "S:80", "I:1", "O:1" */
/* proto_prefix: 0=default(TCP), or from "T:"/"U:"/"S:"/"I:" */
static int parse_port_range(const char *str, portrange_t *out) {
    int proto = PROTO_TCP;
    const char *p = str;

    /* Check for protocol prefix */
    if (toupper(p[0]) == 'T' && p[1] == ':') { proto = PROTO_TCP; p += 2; }
    else if (toupper(p[0]) == 'U' && p[1] == ':') { proto = PROTO_UDP; p += 2; }
    else if (toupper(p[0]) == 'S' && p[1] == ':') { proto = PROTO_SCTP; p += 2; }
    else if (toupper(p[0]) == 'I' && p[1] == ':') { proto = PROTO_ICMP; p += 2; }
    else if (toupper(p[0]) == 'O' && p[1] == ':') { 
        /* ICMP = "O:" maps to I: internally with offset +256 */
        proto = PROTO_ICMP; p += 2;
        /* The value is already shifted internally: 1 -> 257 */
        unsigned begin = atoi(p);
        char *dash = strchr(p, '-');
        unsigned end = dash ? atoi(dash+1) : begin;
        out->proto = proto;
        out->begin = begin + 256;
        out->end = end + 256;
        return 1;
    }

    /* Parse port number or range */
    char *dash = strchr(p, '-');
    if (dash) {
        out->proto = proto;
        out->begin = atoi(p);
        out->end = atoi(dash+1);
    } else {
        out->proto = proto;
        out->begin = atoi(p);
        out->end = atoi(p);
    }
    return 1;
}

/* Compare port ranges for sorting */
/* TCP first (0), then UDP (1), then SCTP (2), then ICMP (3) */
/* Within same protocol, sort by begin port */
static int cmp_ports(const void *a, const void *b) {
    const portrange_t *pa = a, *pb = b;
    if (pa->proto != pb->proto) return pa->proto - pb->proto;
    if (pa->begin != pb->begin) return (int)pa->begin - (int)pb->begin;
    return 0;
}

/* Merge overlapping/adjacent port ranges within same protocol */
static void ports_merge(portrange_t *ports, int *count) {
    if (*count == 0) return;
    qsort(ports, *count, sizeof(portrange_t), cmp_ports);
    int out = 0;
    for (int i = 1; i < *count; i++) {
        if (ports[i].proto == ports[out].proto &&
            ports[i].begin <= ports[out].end + 1) {
            if (ports[i].end > ports[out].end)
                ports[out].end = ports[i].end;
        } else {
            out++;
            ports[out] = ports[i];
        }
    }
    *count = out + 1;
}

