static void parse_ports(MasscanConfig *cfg, const char *str) {
    char tmp[4096];
    strncpy(tmp, str, sizeof(tmp)-1);
    tmp[sizeof(tmp)-1] = '\0';

    char *tok = strtok(tmp, ",");
    while (tok) {
        tok = str_trim(tok);
        if (*tok) {
            portrange_t pr;
            if (parse_port_range(tok, &pr)) {
                if (cfg->nports < MAX_PORTS) {
                    cfg->ports[cfg->nports++] = pr;
                }
            }
        }
        tok = strtok(NULL, ",");
    }
}

/* Format port range for echo output */
/* Returns allocated string, caller frees */
static void fmt_port_range(const portrange_t *pr, char *buf, size_t sz) {
    const char *prefix = "";
    unsigned begin = pr->begin, end = pr->end;

    switch (pr->proto) {
    case PROTO_TCP:  prefix = ""; break;
    case PROTO_UDP:  prefix = "U:"; break;
    case PROTO_SCTP: prefix = "S:"; break;
    case PROTO_ICMP:
        prefix = "I:";
        break;
    }

    if (begin == end)
        snprintf(buf, sz, "%s%u", prefix, begin);
    else
        snprintf(buf, sz, "%s%u-%u", prefix, begin, end);
}

/* Build port string for echo output */
static void build_ports_str(const portrange_t *ports, int nports, char *buf, size_t sz) {
    buf[0] = '\0';
    int first = 1;
    char tmp[64];
    for (int i = 0; i < nports; i++) {
        fmt_port_range(&ports[i], tmp, sizeof(tmp));
        if (!first) strncat(buf, ",", sz - strlen(buf) - 1);
        strncat(buf, tmp, sz - strlen(buf) - 1);
        first = 0;
    }
}

