/* ============================================================ */
/*  NOCAPTURE HANDLING                                          */
/* ============================================================ */

static void nocapture_add(MasscanConfig *cfg, const char *name) {
    if (cfg->nocapture_count < MAX_NOCAP)
        cfg->nocapture[cfg->nocapture_count++] = strdup(name);
}

/* Default nocapture = "servername" */
static void nocapture_set_defaults(MasscanConfig *cfg) {
    /* By default, servername is always nocaptured */
    /* This is added when not using --banners (or even with it) */
    if (cfg->nocapture_count == 0) {
        nocapture_add(cfg, "servername");
    }
}

/* ============================================================ */
/*  CONFIG FILE READING                                         */
/* ============================================================ */

/* Forward declaration */
static int config_set_option(MasscanConfig *cfg, const char *name, const char *value, int is_cmdline);

static int read_config_file(MasscanConfig *cfg, const char *filename) {
    FILE *f = fopen(filename, "r");
    if (!f) {
        fprintf(stderr,"[-] FAIL: reading configuration file\n");
        fprintf(stderr,"[-] %s: %s\n", filename, strerror(errno));
        char cwd[1024];
        if (getcwd(cwd, sizeof(cwd)))
            fprintf(stderr,"[-] cwd = %s\n", cwd);
        return -1;
    }

    char line[4096];
    while (fgets(line, sizeof(line), f)) {
        char *p = str_trim(line);
        if (!*p || *p == '#') continue;

        /* Split on '=' */
        char *eq = strchr(p, '=');
        if (!eq) {
            /* Could be an IP range or similar */
            /* Try treating as a value with no = */
            config_set_option(cfg, p, NULL, 0);
            continue;
        }
        *eq = '\0';
        char *name = str_trim(p);
        char *value = str_trim(eq+1);
        config_set_option(cfg, name, value, 0);
    }
    fclose(f);
    return 0;
}

/* ============================================================ */
/*  OPTION SETTING                                              */
/* ============================================================ */

static void add_exclude_range(MasscanConfig *cfg, const char *str) {
    iprange_t r;
    if (parse_ip_range(str, &r))
        ranges_add(cfg->excludes, &cfg->nexcludes, MAX_RANGES, &r);
}

static int read_exclude_file(MasscanConfig *cfg, const char *filename) {
    FILE *f = fopen(filename, "r");
    if (!f) {
        fprintf(stderr,"[-] %s: %s\n", filename, strerror(errno));
        return 0;
    }
    char line[4096];
