/* The main option setter */
static int config_set_option(MasscanConfig *cfg, const char *name, const char *value, int is_cmdline) {
    (void)is_cmdline;

    if (!name) return 0;

    if (strcmp(name, "rate") == 0 || strcmp(name, "max-rate") == 0) {
        if (value) cfg->rate = atof(value);
    } else if (strcmp(name, "seed") == 0) {
        if (value) { cfg->seed = (uint64_t)strtoull(value, NULL, 10); cfg->seed_set = 1; }
    } else if (strcmp(name, "shard") == 0) {
        if (value) {
            unsigned a, b;
            if (sscanf(value, "%u/%u", &a, &b) == 2) {
                cfg->shard_num = a; cfg->shard_total = b;
            }
        }
    } else if (strcmp(name, "banners") == 0) {
        cfg->banners = (!value || strcmp(value,"true")==0 || strcmp(value,"1")==0) ? 1 : 0;
    } else if (strcmp(name, "heartbleed") == 0) {
        cfg->banners = 1;
        nocapture_add(cfg, "cert");
    } else if (strcmp(name, "nocapture") == 0) {
        if (value) nocapture_add(cfg, value);
    } else if (strcmp(name, "output-filename") == 0) {
        if (value) strncpy(cfg->output_filename, value, MAX_STR-1);
    } else if (strcmp(name, "output-file") == 0) {
        if (value) strncpy(cfg->output_filename, value, MAX_STR-1);
    } else if (strcmp(name, "output-format") == 0) {
        if (value) strncpy(cfg->output_format, value, sizeof(cfg->output_format)-1);
    } else if (strcmp(name, "output-append") == 0) {
        cfg->append_output = (!value || strcmp(value,"true")==0 || strcmp(value,"1")==0) ? 1 : 0;
    } else if (strcmp(name, "ports") == 0) {
        if (value) parse_ports(cfg, value);
    } else if (strcmp(name, "range") == 0 || strcmp(name, "ranges") == 0 ||
               strcmp(name, "target") == 0 || strcmp(name, "targets") == 0) {
        if (value) {
            iprange_t r;
            if (parse_ip_range(value, &r))
                ranges_add(cfg->ranges, &cfg->nranges, MAX_RANGES, &r);
        }
    } else if (strcmp(name, "exclude") == 0) {
        if (value) {
            /* Can be comma-separated */
            char tmp[4096];
            strncpy(tmp, value, sizeof(tmp)-1);
            tmp[sizeof(tmp)-1] = '\0';
            char *tok = strtok(tmp, ",");
            while (tok) {
                add_exclude_range(cfg, str_trim(tok));
                tok = strtok(NULL, ",");
            }
        }
    } else if (strcmp(name, "excludefile") == 0 || strcmp(name, "exclude-file") == 0) {
        if (value) read_exclude_file(cfg, value);
    } else if (strcmp(name, "adapter") == 0) {
        if (value) strncpy(cfg->adapter, value, sizeof(cfg->adapter)-1);
    } else if (strcmp(name, "adapter-ip") == 0) {
        if (value) strncpy(cfg->adapter_ip, value, sizeof(cfg->adapter_ip)-1);
    } else if (strcmp(name, "adapter-mac") == 0) {
        if (value) {
            parse_mac(value, cfg->adapter_mac);
            cfg->adapter_mac_set = 1;
        }
    } else if (strcmp(name, "router-mac") == 0) {
        if (value) {
            parse_mac(value, cfg->router_mac_v4);
            cfg->router_mac_v4_set = 1;
            memcpy(cfg->router_mac_v6, cfg->router_mac_v4, 6);
            cfg->router_mac_v6_set = 1;
        }
    } else if (strcmp(name, "router-mac-ipv4") == 0) {
        if (value) {
            parse_mac(value, cfg->router_mac_v4);
            cfg->router_mac_v4_set = 1;
        }
    } else if (strcmp(name, "router-mac-ipv6") == 0) {
        if (value) {
            parse_mac(value, cfg->router_mac_v6);
            cfg->router_mac_v6_set = 1;
        }
    } else if (strcmp(name, "adapter-port") == 0) {
        if (value) { cfg->adapter_port = atoi(value); cfg->adapter_port_set = 1; }
    } else if (strcmp(name, "ttl") == 0) {
        if (value) { cfg->ttl = atoi(value); cfg->ttl_set = 1; }
    } else if (strcmp(name, "connection-timeout") == 0) {
        if (value) cfg->connection_timeout = atoi(value);
    } else if (strcmp(name, "open") == 0 || strcmp(name, "open-only") == 0) {
        cfg->open_only = 1;
    } else if (strcmp(name, "resume-index") == 0) {
        if (value) { cfg->resume_index = strtoull(value, NULL, 10); cfg->resume_index_set = 1; }
    } else if (strcmp(name, "resume-count") == 0) {
        if (value) { cfg->resume_count = strtoull(value, NULL, 10); cfg->resume_count_set = 1; }
    } else if (strcmp(name, "append-output") == 0) {
        cfg->append_output = 1;
    } else if (strcmp(name, "packet-trace") == 0) {
        cfg->packet_trace = 1;
    } else if (strcmp(name, "send-eth") == 0) {
        /* always on, ignore */
        fprintf(stderr,"nmap(send-eth): unnecessary, we always do --send-eth\n");
    } else if (strcmp(name, "readscan") == 0) {
        cfg->do_readscan = 1;
        if (value) strncpy(cfg->readscan_file, value, MAX_STR-1);
    } else {
        return 0; /* unknown */
    }
    return 1;
}

