static void print_echo(const MasscanConfig *cfg) {
    char buf[MAX_STR];

    /* Resume information (if set) */
    if (cfg->resume_index_set || cfg->resume_count_set) {
        fprintf(stdout,"\n# resume information\n");
        if (cfg->resume_index_set)
            fprintf(stdout,"resume-index = %llu\n", (unsigned long long)cfg->resume_index);
        if (cfg->resume_count_set)
            fprintf(stdout,"resume-count = %llu\n", (unsigned long long)cfg->resume_count);
    }

    /* Seed */
    fprintf(stdout,"seed = %llu\n", (unsigned long long)cfg->seed);

    /* Rate */
    fmt_rate(cfg->rate, buf, sizeof(buf));
    fprintf(stdout,"rate = %s\n", buf);

    /* Shard */
    fprintf(stdout,"shard = %u/%u\n", cfg->shard_num, cfg->shard_total);

    /* Banners */
    if (cfg->banners)
        fprintf(stdout,"banners = true\n");

    /* Nocapture */
    for (int i = 0; i < cfg->nocapture_count; i++)
        fprintf(stdout,"nocapture = %s\n", cfg->nocapture[i]);

    fprintf(stdout,"\n");

    /* Output */
    if (cfg->output_filename[0]) {
        fprintf(stdout,"output-filename = %s\n", cfg->output_filename);
        fprintf(stdout,"output-format = %s\n",
                cfg->output_format[0] ? cfg->output_format : "xml");
    } else if (cfg->output_format[0]) {
        fprintf(stdout,"output-format = %s\n", cfg->output_format);
    }
    if (cfg->append_output)
        fprintf(stdout,"output-append = true\n");

    if (cfg->output_filename[0] || cfg->output_format[0] || cfg->append_output)
        fprintf(stdout,"\n");

    /* Adapter settings */
    if (cfg->adapter[0])
        fprintf(stdout,"adapter = %s\n", cfg->adapter);
    if (cfg->adapter_ip[0])
        fprintf(stdout,"adapter-ip = %s\n", cfg->adapter_ip);
    if (cfg->adapter_mac_set) {
        fmt_mac(cfg->adapter_mac, buf, sizeof(buf));
        fprintf(stdout,"adapter-mac = %s\n", buf);
    }
    if (cfg->router_mac_v4_set) {
        fmt_mac(cfg->router_mac_v4, buf, sizeof(buf));
        fprintf(stdout,"router-mac-ipv4 = %s\n", buf);
    }
    if (cfg->router_mac_v6_set) {
        fmt_mac(cfg->router_mac_v6, buf, sizeof(buf));
        fprintf(stdout,"router-mac-ipv6 = %s\n", buf);
    }
    if (cfg->adapter_port_set)
        fprintf(stdout,"adapter-port = %d\n", cfg->adapter_port);

    /* Target selection */
    fprintf(stdout,"# TARGET SELECTION (IP, PORTS, EXCLUDES)\n");

    /* Ports */
    build_ports_str(cfg->ports, cfg->nports, buf, sizeof(buf));
    fprintf(stdout,"ports = %s\n", buf);

    /* Ranges */
    for (int i = 0; i < cfg->nranges; i++) {
        if (cfg->ranges[i].is_v6) {
            fmt_ipv6_range(&cfg->ranges[i], buf, sizeof(buf));
        } else {
            fmt_ipv4_range(cfg->ranges[i].first.v4, cfg->ranges[i].last.v4,
                           buf, sizeof(buf));
        }
        fprintf(stdout,"range = %s\n", buf);
    }
}

