/* ============================================================ */
/*  ARGUMENT PARSING                                            */
/* ============================================================ */

/* Get next argument value, advancing index */
static const char *get_next_arg(int argc, char **argv, int *i) {
    if (*i + 1 >= argc) return NULL;
    return argv[++(*i)];
}

/* Sets output format and optionally filename from -oX style options */
static void set_output_shorthand(MasscanConfig *cfg, char fmt, const char *filename) {
    switch (tolower(fmt)) {
    case 'x': strncpy(cfg->output_format, "xml", sizeof(cfg->output_format)-1); break;
    case 'j': strncpy(cfg->output_format, "json", sizeof(cfg->output_format)-1); break;
    case 'd': strncpy(cfg->output_format, "ndjson", sizeof(cfg->output_format)-1); break;
    case 'g': strncpy(cfg->output_format, "grepable", sizeof(cfg->output_format)-1); break;
    case 'b': strncpy(cfg->output_format, "binary", sizeof(cfg->output_format)-1); break;
    case 'u': strncpy(cfg->output_format, "unicornscan", sizeof(cfg->output_format)-1); break;
    case 'l': strncpy(cfg->output_format, "list", sizeof(cfg->output_format)-1); break;
    }
    if (filename)
        strncpy(cfg->output_filename, filename, MAX_STR-1);
}

/* Parse command-line arguments.
   Returns:  0 = continue to scan
            -1 = error (print usage, exit 1)
             1 = special mode (echo done, exit 0)
             2 = print help+exit1
             3 = print nmap+exit1
             4 = print version+exit1
*/
static int parse_args(MasscanConfig *cfg, int argc, char **argv) {
    int i;
    int has_ports = 0;
    int has_ranges = 0;

    /* First pass: get verbosity */
    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-v") == 0) g_verbosity++;
        else if (strcmp(argv[i], "-vv") == 0) g_verbosity += 2;
        else if (strcmp(argv[i], "-vvv") == 0) g_verbosity += 3;
        else if (strncmp(argv[i], "-v", 2) == 0 && argv[i][2] == '\0') g_verbosity++;
    }

    /* Check for early-exit modes (--help, --nmap, -V) */
    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0 || strcmp(argv[i], "-h") == 0)
            return 2;
        if (strcmp(argv[i], "--nmap") == 0)
            return 3;
        if (strcmp(argv[i], "-V") == 0 || strcmp(argv[i], "--version") == 0)
            return 4;
    }

    /* Process arguments */
    for (i = 1; i < argc; i++) {
        char *arg = argv[i];
        char *val = NULL;

        /* Handle --option=value form */
        char *eq = strchr(arg, '=');
        if (eq && arg[0] == '-' && arg[1] == '-') {
            /* Make a copy */
            char argcopy[512];
            strncpy(argcopy, arg, sizeof(argcopy)-1);
            argcopy[sizeof(argcopy)-1] = '\0';
            eq = strchr(argcopy, '=');
            *eq = '\0';
            arg = argcopy;
            val = eq+1;
        }

        /* Skip -v flags */
        if (strcmp(arg, "-v") == 0 || strncmp(arg, "-vv", 3) == 0) continue;
        if (strcmp(arg, "-d") == 0 || strncmp(arg, "-dd", 3) == 0) continue;

        /* ---- Ports ---- */
        if (strcmp(arg, "-p") == 0 || strcmp(arg, "--ports") == 0 || strcmp(arg, "--port") == 0) {
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (!val) {
                fprintf(stderr, "(null): empty parameter\n");
                return -1;
            }
            parse_ports(cfg, val);
            has_ports = 1;
        }
        /* Short -pPORT form */
        else if (arg[0] == '-' && arg[1] == 'p' && arg[2] != '\0') {
            parse_ports(cfg, arg+2);
            has_ports = 1;
        }
        /* ---- Output ---- */
        else if (strcmp(arg, "--output-format") == 0) {
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (val) strncpy(cfg->output_format, val, sizeof(cfg->output_format)-1);
        }
        else if (strcmp(arg, "--output-filename") == 0 || strcmp(arg, "--output-file") == 0) {
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (val) strncpy(cfg->output_filename, val, MAX_STR-1);
        }
        else if (strcmp(arg, "--append-output") == 0) {
            cfg->append_output = 1;
        }
        else if (arg[0] == '-' && arg[1] == 'o' && arg[2] != '\0') {
            char fmt = arg[2];
            const char *fname = NULL;
            if (arg[3] != '\0') fname = arg+3;
            else fname = get_next_arg(argc, argv, &i);
            set_output_shorthand(cfg, fmt, fname);
        }
        /* ---- Rate ---- */
        else if (strcmp(arg, "--rate") == 0 || strcmp(arg, "--max-rate") == 0) {
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (val) cfg->rate = atof(val);
        }
        /* ---- Seed ---- */
        else if (strcmp(arg, "--seed") == 0) {
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (val) { cfg->seed = (uint64_t)strtoull(val, NULL, 10); cfg->seed_set = 1; }
        }
        /* ---- Shard ---- */
        else if (strcmp(arg, "--shard") == 0) {
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (val) {
                unsigned a, b;
                if (sscanf(val, "%u/%u", &a, &b) == 2) {
                    cfg->shard_num = a; cfg->shard_total = b;
                }
            }
        }
        /* ---- Banners ---- */
        else if (strcmp(arg, "--banners") == 0 || strcmp(arg, "--banner") == 0) {
            cfg->banners = 1;
        }
        else if (strcmp(arg, "--heartbleed") == 0) {
            cfg->banners = 1;
            /* cert will be added as nocapture */
            nocapture_add(cfg, "cert");
        }
        /* ---- Nocapture ---- */
        else if (strcmp(arg, "--nocapture") == 0) {
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (val) {
                /* Validate nocapture value */
                if (strcmp(val, "cert") == 0) {
                    nocapture_add(cfg, val);
                } else if (strcmp(val, "servername") == 0 ||
                           strcmp(val, "html") == 0) {
                    /* valid but default/silent */
                } else {
                    fprintf(stderr, "FAIL: %s: unknown nocapture type\n", val);
                }
            }
        }
        /* ---- Adapter ---- */
        else if (strcmp(arg, "-e") == 0) {
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (val) strncpy(cfg->adapter, val, sizeof(cfg->adapter)-1);
        }
        else if (strcmp(arg, "--adapter") == 0 || strcmp(arg, "--if") == 0) {
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (val) strncpy(cfg->adapter, val, sizeof(cfg->adapter)-1);
        }
        else if (strcmp(arg, "--adapter-ip") == 0 || strcmp(arg, "--source-ip") == 0 ||
                 strcmp(arg, "-S") == 0) {
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (val) strncpy(cfg->adapter_ip, val, sizeof(cfg->adapter_ip)-1);
        }
        else if (strcmp(arg, "--adapter-mac") == 0 || strcmp(arg, "--spoof-mac") == 0) {
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (val) {
                parse_mac(val, cfg->adapter_mac);
                cfg->adapter_mac_set = 1;
            }
        }
        else if (strcmp(arg, "--router-mac") == 0) {
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (val) {
                parse_mac(val, cfg->router_mac_v4);
                cfg->router_mac_v4_set = 1;
                memcpy(cfg->router_mac_v6, cfg->router_mac_v4, 6);
                cfg->router_mac_v6_set = 1;
            }
        }
        else if (strcmp(arg, "--router-mac-ipv4") == 0) {
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (val) {
                parse_mac(val, cfg->router_mac_v4);
                cfg->router_mac_v4_set = 1;
            }
        }
        else if (strcmp(arg, "--router-mac-ipv6") == 0) {
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (val) {
                parse_mac(val, cfg->router_mac_v6);
                cfg->router_mac_v6_set = 1;
            }
        }
        else if (strcmp(arg, "--adapter-port") == 0 || strcmp(arg, "--source-port") == 0 ||
                 strcmp(arg, "-g") == 0) {
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (val) { cfg->adapter_port = atoi(val); cfg->adapter_port_set = 1; }
        }
        /* ---- TTL ---- */
        else if (strcmp(arg, "--ttl") == 0) {
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (val) { cfg->ttl = atoi(val); cfg->ttl_set = 1; }
        }
        /* ---- Connection timeout ---- */
        else if (strcmp(arg, "--connection-timeout") == 0) {
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (val) cfg->connection_timeout = atoi(val);
        }
        /* ---- Open ---- */
        else if (strcmp(arg, "--open") == 0 || strcmp(arg, "--open-only") == 0) {
            cfg->open_only = 1;
        }
        /* ---- Packet trace ---- */
        else if (strcmp(arg, "--packet-trace") == 0) {
            cfg->packet_trace = 1;
        }
        /* ---- Send-eth ---- */
        else if (strcmp(arg, "--send-eth") == 0) {
            fprintf(stderr, "nmap(send-eth): unnecessary, we always do --send-eth\n");
        }
        /* ---- Exclude ---- */
        else if (strcmp(arg, "--exclude") == 0) {
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (val) {
                char tmp[4096];
                strncpy(tmp, val, sizeof(tmp)-1);
                tmp[sizeof(tmp)-1] = '\0';
                char *tok = strtok(tmp, ",");
                while (tok) {
                    add_exclude_range(cfg, str_trim(tok));
                    tok = strtok(NULL, ",");
                }
            }
        }
        else if (strcmp(arg, "--excludefile") == 0 || strcmp(arg, "--exclude-file") == 0) {
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (val) read_exclude_file(cfg, val);
        }
        /* ---- Include file ---- */
        else if (strcmp(arg, "-iL") == 0 || strcmp(arg, "--include-file") == 0) {
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (val) {
                read_include_file(cfg, val);
                has_ranges = 1;
            }
        }
        /* ---- Config file ---- */
        else if (strcmp(arg, "-c") == 0 || strcmp(arg, "--conf") == 0) {
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (val) {
                if (read_config_file(cfg, val) < 0) return -1;
            }
        }
        else if (strcmp(arg, "--resume") == 0) {
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (val) {
                if (read_config_file(cfg, val) < 0) return -1;
            }
        }
        /* ---- Resume index/count ---- */
        else if (strcmp(arg, "--resume-index") == 0) {
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (val) { cfg->resume_index = strtoull(val, NULL, 10); cfg->resume_index_set = 1; }
        }
        else if (strcmp(arg, "--resume-count") == 0) {
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (val) { cfg->resume_count = strtoull(val, NULL, 10); cfg->resume_count_set = 1; }
        }
        /* ---- Echo ---- */
        else if (strcmp(arg, "--echo") == 0) {
            cfg->do_echo = 1;
        }
        /* ---- List interfaces ---- */
        else if (strcmp(arg, "--iflist") == 0) {
            cfg->do_iflist = 1;
        }
        /* ---- Readscan ---- */
        else if (strcmp(arg, "--readscan") == 0) {
            cfg->do_readscan = 1;
            if (!val) val = (char*)get_next_arg(argc, argv, &i);
            if (val) strncpy(cfg->readscan_file, val, MAX_STR-1);
        }
        /* ---- Randomize/nmap compat flags ---- */
        else if (strcmp(arg, "-sS") == 0 || strcmp(arg, "-Pn") == 0 ||
                 strcmp(arg, "-n") == 0 || strcmp(arg, "--randomize-hosts") == 0) {
            /* silently accepted */
        }
        /* ---- Unknown double-dash ---- */
        else if (arg[0] == '-' && arg[1] == '-') {
            char optname[256];
            strncpy(optname, arg+2, sizeof(optname)-1);
            optname[sizeof(optname)-1] = '\0';
            /* Strip any =value part */
            char *eq2 = strchr(optname, '=');
            if (eq2) *eq2 = '\0';
            fprintf(stderr, "%s: empty parameter\n", optname);
            return -1;
        }
        /* ---- Unknown single-dash ---- */
        else if (arg[0] == '-' && arg[1] != '\0') {
            fprintf(stderr, "%s: empty parameter\n", arg+1);
            return -1;
        }
        /* ---- IP range (non-option argument) ---- */
        else {
            iprange_t r;
            if (parse_ip_range(arg, &r)) {
                ranges_add(cfg->ranges, &cfg->nranges, MAX_RANGES, &r);
                has_ranges = 1;
            } else {
                fprintf(stderr, "FAIL: unknown command-line parameter \"%s\"\n", arg);
                fprintf(stderr, " [hint] did you want \"--%s\"?\n", arg);
                return -1;
            }
        }
    }

    return 0; /* normal */
}

