/* ============================================================ */
/*  INTERFACE DETECTION                                         */
/* ============================================================ */

/* Find default network interface (the one with the default route) */
static void find_default_interface(char *ifname, size_t sz) {
    /* Read /proc/net/route to find default gateway interface */
    FILE *f = fopen("/proc/net/route", "r");
    if (f) {
        char line[256];
        fgets(line, sizeof(line), f); /* skip header */
        while (fgets(line, sizeof(line), f)) {
            char iface[64], dest[16];
            unsigned flags;
            if (sscanf(line, "%63s %15s %*s %x", iface, dest, &flags) >= 3) {
                if (strcmp(dest, "00000000") == 0 && (flags & 0x2)) {
                    strncpy(ifname, iface, sz-1);
                    fclose(f);
                    return;
                }
            }
        }
        fclose(f);
    }

    /* Fallback: use first non-loopback interface */
    struct ifaddrs *ifaddrs;
    if (getifaddrs(&ifaddrs) == 0) {
        struct ifaddrs *ifa;
        for (ifa = ifaddrs; ifa; ifa = ifa->ifa_next) {
            if (!ifa->ifa_addr) continue;
            if (ifa->ifa_flags & IFF_LOOPBACK) continue;
            if (ifa->ifa_addr->sa_family == AF_INET) {
                strncpy(ifname, ifa->ifa_name, sz-1);
                freeifaddrs(ifaddrs);
                return;
            }
        }
        freeifaddrs(ifaddrs);
    }

    /* Last resort */
    strncpy(ifname, "eth0", sz-1);
}

/* ============================================================ */
/*  SCAN EXECUTION                                              */
/* ============================================================ */

static int do_readscan(MasscanConfig *cfg) {
    fprintf(stderr,"[+] --readscan %s\n", cfg->readscan_file);
    FILE *f = fopen(cfg->readscan_file, "rb");
    if (!f) {
        fprintf(stderr,"[-] %s: %s\n", cfg->readscan_file, strerror(errno));
        return 0;
    }
    /* Check for masscan binary format header */
    char magic[12] = {0};
    fread(magic, 1, 11, f);
    fclose(f);
    if (strncmp(magic, "masscan/1.1", 11) != 0) {
        fprintf(stderr,"[-] %s: unknown file format (expeced \"masscan/1.1\")\n",
                cfg->readscan_file);
        return 0;
    }
    fprintf(stderr,"[-] %s: Success\n", cfg->readscan_file);
    return 0;
}

static int do_scan(MasscanConfig *cfg) {
    /* Find the interface */
    char ifname[64] = "eth0";
    if (cfg->adapter[0])
        strncpy(ifname, cfg->adapter, sizeof(ifname)-1);
    else
        find_default_interface(ifname, sizeof(ifname));

    if (g_verbosity >= 1) {
        fprintf(stderr,"[+] interface = %s\n", ifname);
        const char *ver = "stub/0.0";
        if (g_pcap_ok) {
            const char *(*fn)(void) = pcap_sym("pcap_lib_version");
            if (fn) ver = fn();
        }
        fprintf(stderr,"[+] if(%s): pcap: %s\n", ifname, ver);
    }

    if (!g_pcap_ok) {
        fprintf(stderr,"FAIL:%s: can't open adapter: libpcap not loaded\n", ifname);
        fprintf(stderr,"[-] if:%s:init: failed\n", ifname);
        return 1;
    }

    /* Try to open the interface */
    char errbuf[PCAP_ERRBUF_SIZE] = {0};
    void *pcap_handle = wrap_pcap_open_live(ifname, 65535, 1, 1000, errbuf);
    if (!pcap_handle) {
        fprintf(stderr,"FAIL:%s: can't open adapter: %s\n", ifname, errbuf);
        fprintf(stderr,"[-] if:%s:init: failed\n", ifname);
        return 1;
    }

    /* Close it - actual scanning would happen here */
    wrap_pcap_close(pcap_handle);

    /* Check required parameters */
    if (cfg->nports == 0) {
        fprintf(stderr,"FAIL: no ports were specified\n");
        fprintf(stderr," [hint] try something like \"-p80,8000-9000\"\n");
        fprintf(stderr," [hint] try something like \"--ports 0-65535\"\n");
        return 1;
    }
    if (cfg->nranges == 0) {
        fprintf(stderr,"FAIL: target IP address list empty\n");
        fprintf(stderr," [hint] try something like \"--range 10.0.0.0/8\"\n");
        fprintf(stderr," [hint] try something like \"--range 192.168.0.100-192.168.0.200\"\n");
        return 1;
    }

    return 0;
}

