int main(int argc, char *argv[]) {
    MasscanConfig cfg;
    config_init(&cfg);

    /* Parse arguments - first check for quick-exit modes */
    int ret = parse_args(&cfg, argc, argv);

    switch (ret) {
    case 2: /* --help */
