    if (!cfg.seed_set)
        cfg.seed = random_seed();

    /* Handle --iflist */
    if (cfg.do_iflist) {
        if (!g_pcap_ok)
            fprintf(stderr,"libpcap not loaded\n");
        else {
            /* List interfaces via pcap */
            char errbuf[PCAP_ERRBUF_SIZE];
            void *alldevs = NULL;
            if (wrap_pcap_findalldevs(&alldevs, errbuf) == 0 && alldevs) {
                /* Print interfaces - simplified */
                wrap_pcap_freealldevs(alldevs);
            }
        }
        return 0;
