    if (cfg.do_echo) {
        /* Check for IPv6 range size overflow */
        for (int i = 0; i < cfg.nranges; i++) {
            if (cfg.ranges[i].is_v6) {
                /* Check if range is too large */
                iprange_t *r = &cfg.ranges[i];
                /* Count bits in range */
                /* prefix = bits set from top of /128 */
                uint64_t dhi = r->first.v6.hi ^ r->last.v6.hi;
                uint64_t dlo = r->first.v6.lo ^ r->last.v6.lo;
                /* bits_used = 128 - common_prefix_bits */
                int range_bits = 0;
                if (dhi != 0) {
                    range_bits = 64;
                    uint64_t tmp = dhi;
                    while (tmp > 0) { tmp >>= 1; range_bits++; }
                } else {
                    uint64_t tmp = dlo;
                    while (tmp > 0) { tmp >>= 1; range_bits++; }
                }
                /* range_bits includes ports */
                int port_bits = 0;
                {
                    int total_ports = 0;
                    for (int j = 0; j < cfg.nports; j++)
                        total_ports += cfg.ports[j].end - cfg.ports[j].begin + 1;
                    int tmp2 = total_ports - 1;
                    while (tmp2 > 0) { tmp2 >>= 1; port_bits++; }
                }
                int total_bits = range_bits + port_bits;
                if (total_bits > 63) {
                    fprintf(stderr,"[-] FAIL: scan range too large, max is 63-bits, requested is %d bits\n", total_bits);
                    fprintf(stderr,"    Hint: scan range is number of IP addresses times number of ports\n");
                    fprintf(stderr,"    Hint: IPv6 subnet must be at least /66 \n");
                    return 1;
                }
            }
        }

        /* Sort/merge ranges and apply excludes */
        /* Separate IPv4 and IPv6 ranges */
        iprange_t v4ranges[MAX_RANGES], v6ranges[MAX_RANGES];
        int nv4 = 0, nv6 = 0;
        for (int i = 0; i < cfg.nranges; i++) {
            if (cfg.ranges[i].is_v6)
                v6ranges[nv6++] = cfg.ranges[i];
            else
                v4ranges[nv4++] = cfg.ranges[i];
        }

        /* Sort/merge IPv4 */
        ranges_merge_v4(v4ranges, &nv4);

        /* Apply excludes to IPv4 */
        if (cfg.nexcludes > 0) {
            iprange_t excv4[MAX_RANGES];
            int nexcv4 = 0;
            for (int i = 0; i < cfg.nexcludes; i++)
                if (!cfg.excludes[i].is_v6)
                    excv4[nexcv4++] = cfg.excludes[i];
            ranges_merge_v4(excv4, &nexcv4);
            ranges_subtract_v4(v4ranges, &nv4, excv4, nexcv4);
        }

        /* Merge ports */
        ports_merge(cfg.ports, &cfg.nports);

        /* Rebuild ranges */
        cfg.nranges = 0;
        for (int i = 0; i < nv4; i++)
