        fprintf(stdout,"seed = %llu\n", (unsigned long long)cfg.seed);

        /* rate */
        char ratebuf[64];
        fmt_rate(cfg.rate, ratebuf, sizeof(ratebuf));
        fprintf(stdout,"rate = %s\n", ratebuf);

        /* shard */
        fprintf(stdout,"shard = %u/%u\n", cfg.shard_num, cfg.shard_total);

        /* banners */
        if (cfg.banners)
            fprintf(stdout,"banners = true\n");

        /* nocapture - printed twice */
        print_nocapture_echo(cfg.banners, has_cert);

        fprintf(stdout,"\n");

        /* output settings */
        int has_output = (cfg.output_filename[0] || cfg.output_format[0] || cfg.append_output);
        if (cfg.output_filename[0]) {
            fprintf(stdout,"output-filename = %s\n", cfg.output_filename);
            fprintf(stdout,"output-format = %s\n",
                    cfg.output_format[0] ? cfg.output_format : "xml");
        } else if (cfg.output_format[0]) {
            fprintf(stdout,"output-format = %s\n", cfg.output_format);
        }
        if (cfg.append_output)
            fprintf(stdout,"output-append = true\n");

        if (has_output)
            fprintf(stdout,"\n");

        /* adapter settings */
        if (cfg.adapter[0])
            fprintf(stdout,"adapter = %s\n", cfg.adapter);
        if (cfg.adapter_ip[0])
            fprintf(stdout,"adapter-ip = %s\n", cfg.adapter_ip);
        if (cfg.adapter_mac_set) {
            char macbuf[32];
            fmt_mac(cfg.adapter_mac, macbuf, sizeof(macbuf));
            fprintf(stdout,"adapter-mac = %s\n", macbuf);
        }
        if (cfg.router_mac_v4_set) {
            char macbuf[32];
            fmt_mac(cfg.router_mac_v4, macbuf, sizeof(macbuf));
            fprintf(stdout,"router-mac-ipv4 = %s\n", macbuf);
        }
        if (cfg.router_mac_v6_set) {
            char macbuf[32];
            fmt_mac(cfg.router_mac_v6, macbuf, sizeof(macbuf));
            fprintf(stdout,"router-mac-ipv6 = %s\n", macbuf);
        }
        if (cfg.adapter_port_set)
            fprintf(stdout,"adapter-port = %d\n", cfg.adapter_port);

        /* Target selection header */
        fprintf(stdout,"# TARGET SELECTION (IP, PORTS, EXCLUDES)\n");

        /* Ports */
        {
            char portbuf[65536] = "";
            build_ports_str(cfg.ports, cfg.nports, portbuf, sizeof(portbuf));
            fprintf(stdout,"ports = %s\n", portbuf);
        }

        /* Ranges */
        for (int i = 0; i < cfg.nranges; i++) {
            char rbuf[256];
            if (cfg.ranges[i].is_v6)
                fmt_ipv6_range(&cfg.ranges[i], rbuf, sizeof(rbuf));
            else
                fmt_ipv4_range(cfg.ranges[i].first.v4, cfg.ranges[i].last.v4, rbuf, sizeof(rbuf));
            fprintf(stdout,"range = %s\n", rbuf);
        }

        return 0;
    }

    /* Normal scan */

    /* Check range size for IPv6 */
    for (int i = 0; i < cfg.nranges; i++) {
        if (cfg.ranges[i].is_v6) {
            iprange_t *r = &cfg.ranges[i];
