# There's a subtle issue: when -v is set and we try each pcap library,
# I'm printing "failed to load" for each lib INCLUDING the one after which 
# loading succeeds (if loading succeeds). Since no lib loads here, all fail.
# But if one DOES load, I'd still have printed "failed to load" for it.
# Let me fix this: print the failure message ONLY if the load failed.

python3 << 'EOF'
with open('/workspace/src/masscan.c', 'r') as f:
    content = f.read()

old = '''static void pcap_init(void) {
    int i;
    for (i = 0; s_pcap_libs[i]; i++) {
        g_pcap_dl = dlopen(s_pcap_libs[i], RTLD_LAZY);
        if (g_pcap_dl) break;
        if (g_verbosity >= 1)
            fprintf(stderr,"[-] pcap: failed to load: %s\\n", s_pcap_libs[i]);
    }'''

new = '''static void pcap_init(void) {
    int i;
    for (i = 0; s_pcap_libs[i]; i++) {
